package pool

import (
	"context"
	"fmt"
	"sync"
)

// IndexError reports which input failed.
type IndexError struct {
	Index int
	Err   error
}

func (e *IndexError) Error() string { return fmt.Sprintf("pool: input %d: %v", e.Index, e.Err) }
func (e *IndexError) Unwrap() error { return e.Err }

// Map calls fn on every element of in using at most workers goroutines
// (workers < 1 means 1) and returns the results in input order: out[i] is
// fn(ctx, in[i]).
//
// If any call returns an error, Map stops handing out new inputs, waits for
// running calls to return, and returns a nil slice and an *IndexError for the
// failing input with the LOWEST index among those that failed.
//
// If ctx is cancelled, Map stops handing out new inputs, waits for running
// calls to return, and returns ctx.Err() (unless a call failed first, in which
// case the rule above applies). Map never leaks goroutines: when it returns,
// all workers have exited.
func Map[T, R any](ctx context.Context, in []T, workers int, fn func(context.Context, T) (R, error)) ([]R, error) {
	if workers < 1 {
		workers = 1
	}
	type result struct {
		r   R
		err error
		i   int
	}
	jobs := make(chan int)
	results := make(chan result)
	stop := make(chan struct{}) // closed as soon as Map must stop handing out new inputs
	stopOnce := sync.OnceFunc(func() { close(stop) })
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-stop:
					return
				case i, ok := <-jobs:
					if !ok {
						return // dispatcher exhausted the input
					}
					r, err := fn(ctx, in[i])
					results <- result{r: r, err: err, i: i}
				}
			}
		}()
	}
	// Dispatcher: hand out inputs until exhausted, or until work must stop.
	go func() {
		for i := range in {
			select {
			case <-stop:
				return
			case <-ctx.Done():
				stopOnce()
				return
			case jobs <- i:
			}
		}
		close(jobs)
	}()
	// Closer: results is closed only after every worker has exited, so the
	// collector below is guaranteed to have observed all results.
	go func() {
		wg.Wait()
		close(results)
	}()
	out := make([]R, len(in))
	var (
		ctxDone bool   // ctx was cancelled while Map was running
		ctxFirst bool  // cancellation was observed before any call failure
		failFirst bool // a call failure was observed before cancellation
		failed   *IndexError // failing input with the lowest index
	)
finish:
	for {
		select {
		case <-ctx.Done():
			ctxDone = true
			if !failFirst {
				ctxFirst = true
			}
			stopOnce()
		case res, ok := <-results:
			if !ok {
				break finish
			}
			out[res.i] = res.r // results are stored by input index, keeping input order
			if res.err != nil {
				if !ctxFirst {
					failFirst = true
				}
				stopOnce()
				if failed == nil || res.i < failed.Index {
					failed = &IndexError{Index: res.i, Err: res.err}
				}
			}
		}
	}
	if failFirst {
		return nil, failed
	}
	if ctxDone {
		return nil, ctx.Err()
	}
	return out, nil
}
