   85			ctxDone   bool        // ctx was cancelled while Map was running
   86			ctxFirst  bool        // cancellation was observed before any call failure
   87			failFirst bool        // a call failure was observed before cancellation
   88			failed    *IndexError // failing input with the lowest index
   89		)
   90	finish:
   91		for {
   92			select {
   93			case <-ctx.Done():
   94				ctxDone = true
   95				if !failFirst {
   96					ctxFirst = true
   97				}
   98				stopOnce()
   99			case res, ok := <-results:
  100				if !ok {
  101					break finish
  102				}
  103				out[res.i] = res.r // results are stored by input index, keeping input order
  104				if res.err != nil {
  105					if !ctxFirst {
  106						failFirst = true
  107					}
  108					stopOnce()
  109					if failed == nil || res.i < failed.Index {
  110						failed = &IndexError{Index: res.i, Err: res.err}
  111					}
  112				}
  113			}
  114		}
  115		if failFirst {
  116			return nil, failed
  117		}
  118		if ctxDone {
  119			return nil, ctx.Err()
  120		}
  121		return out, nil
  122	}
